mapper.select:
SELECT A.ROLE_CODE AS mhsBrandcd, A.CENTER_ID AS mhsCentercd, A.CENTER_NM AS mhsCenternm, CASE CENTER_USEYN WHEN 'Y' THEN '사용' ELSE '미사용' END AS mhsCenterstatusTxt FROM TB_CENTERINFO A WHERE 1=1
AND A.ROLE_CODE = #{mhsBrandcd}
AND A.CENTER_ID = #{mhsCentercd}
ORDER BY A.CENTER_ID ASC, A.CENTER_NM ASC
